import{_ as e,o as t,c as i,a0 as a}from"./chunks/framework.BGyYNsHo.js";const m=JSON.parse('{"title":"How to Troubleshoot Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/07-troubleshoot.md","filePath":"how-to/07-troubleshoot.md"}'),r={name:"how-to/07-troubleshoot.md"};function s(n,o,l,d,c,h){return t(),i("div",null,[...o[0]||(o[0]=[a('<h1 id="how-to-troubleshoot-local-swmm" tabindex="-1">How to Troubleshoot Local SWMM <a class="header-anchor" href="#how-to-troubleshoot-local-swmm" aria-label="Permalink to &quot;How to Troubleshoot Local SWMM&quot;">​</a></h1><p>Fix common problems with the map, simulations, the WASM build, and learn the known gotchas of this codebase.</p><h2 id="how-to-fix-a-blank-map-no-tiles" tabindex="-1">How to fix a blank map / no tiles <a class="header-anchor" href="#how-to-fix-a-blank-map-no-tiles" aria-label="Permalink to &quot;How to fix a blank map / no tiles&quot;">​</a></h2><ul><li><code>public/config.js</code> missing or token empty → create it with a valid <code>MAPBOX_ACCESS_TOKEN</code> (see <a href="./02-configure.html">How to Configure Local SWMM</a>).</li><li>Browser blocked by CSP? Check the console for CSP violations against <code>api.mapbox.com</code>.</li></ul><h2 id="how-to-fix-run-errors-immediately-with-a-warning" tabindex="-1">How to fix &quot;Run&quot; errors immediately with a warning <a class="header-anchor" href="#how-to-fix-run-errors-immediately-with-a-warning" aria-label="Permalink to &quot;How to fix &quot;Run&quot; errors immediately with a warning&quot;">​</a></h2><ul><li>Cause: no nodes or no outfall in the model.</li><li>Fix: add at least one node and one <code>OUTFALL</code> connected to the network.</li></ul><h2 id="how-to-fix-a-simulation-that-fails-silently-with-engine-errors" tabindex="-1">How to fix a simulation that fails silently / with engine errors <a class="header-anchor" href="#how-to-fix-a-simulation-that-fails-silently-with-engine-errors" aria-label="Permalink to &quot;How to fix a simulation that fails silently / with engine errors&quot;">​</a></h2><ol><li>Check the <strong>Run Status</strong> window, then the <strong>Report</strong> tab. For deep diagnostics, the worker dumps the <code>.rpt</code> error lines and the first 3000 characters of the INP on failure (<code>simWorker.js</code>).</li><li>Reproduce in Node: <code>node scripts/bench-1d.mjs model.inp</code> prints engine error codes (<code>SWMM_ERR_LIFECYCLE = 6</code> is the normal completion code).</li></ol><h2 id="how-to-fix-a-wasm-build-failing-at-pluginfactory-cpp-46-unsupported-platform" tabindex="-1">How to fix a WASM build failing at <code>PluginFactory.cpp:46: unsupported platform</code> <a class="header-anchor" href="#how-to-fix-a-wasm-build-failing-at-pluginfactory-cpp-46-unsupported-platform" aria-label="Permalink to &quot;How to fix a WASM build failing at `PluginFactory.cpp:46: unsupported platform`&quot;">​</a></h2><ul><li>Cause: the submodule was re-pinned without the wasm-compat commit.</li><li>Fix: restore <code>85e4be38</code> (see <a href="./03-build-from-source.html">How to Build the WASM Engine from Source</a>, section 5) or re-apply the Emscripten no-ops.</li></ul><h2 id="how-to-fix-could-not-find-zip-during-vcpkg-bootstrap" tabindex="-1">How to fix <code>Could not find zip</code> during vcpkg bootstrap <a class="header-anchor" href="#how-to-fix-could-not-find-zip-during-vcpkg-bootstrap" aria-label="Permalink to &quot;How to fix `Could not find zip` during vcpkg bootstrap&quot;">​</a></h2><ul><li>Cause: missing system <code>zip</code>/<code>unzip</code>/<code>tar</code>.</li><li>Fix: on Arch Linux: <code>sudo pacman -S zip unzip tar</code>; on Debian/Ubuntu: <code>sudo apt install zip unzip tar</code>.</li></ul><h2 id="how-to-fix-stale-wasm-being-served" tabindex="-1">How to fix stale wasm being served <a class="header-anchor" href="#how-to-fix-stale-wasm-being-served" aria-label="Permalink to &quot;How to fix stale wasm being served&quot;">​</a></h2><ul><li>The server sends <code>Cache-Control: no-store</code>, but if you&#39;re hosting elsewhere, hard-refresh after rebuilding (<code>swmm6wasm.js?v=&lt;n&gt;</code> query params are used in <code>index.html</code>).</li></ul><h2 id="known-gotchas-oddities" tabindex="-1">Known gotchas &amp; oddities <a class="header-anchor" href="#known-gotchas-oddities" aria-label="Permalink to &quot;Known gotchas &amp; oddities&quot;">​</a></h2><ol><li><strong>README drift:</strong> README Quick Start historically referenced <code>cd SWMM_3D_Web_UI</code> and <code>http://localhost:8000</code>; the directory is <code>LocalSWMM</code> and the server port is <code>8080</code>.</li><li><strong>Engine binary naming:</strong> The active WebAssembly engine is delivered via <code>swmm6wasm.js</code> and <code>swmm6wasm.wasm</code>, loaded by <code>simWorker.js</code>.</li><li><strong><code>simWorker</code> progress messages:</strong> The worker completes calculations asynchronously in stride loops; the progress bar provides visual feedback during computation.</li><li><strong>Binary output parsing:</strong> <code>swmmOutParser.js</code> parses <code>.out</code> binary files for performance, with <code>.rpt</code> parsing providing summary table fallbacks.</li><li><strong><code>bench-1d.mjs</code> comment:</strong> <code>bench-1d.mjs</code> carries a legacy header comment referring to <code>probe-1d.mjs</code>.</li><li><strong>LID layer parameters:</strong> LID layer parameters are parsed into <code>rawSections</code> (<code>inpParser.js</code>) so that round-trips preserve the model configuration accurately.</li><li><strong>Config declarations:</strong> CI <code>config.js</code> uses <code>const CONFIG</code> while local configs use <code>var</code>; <code>window.CONFIG</code> lookups are defensive either way.</li><li><strong>vcpkg manifest layering:</strong> The engine&#39;s own <code>vcpkg.json</code> is ignored for the WASM build; only the root manifest applies.</li></ol>',16)])])}const p=e(r,[["render",s]]);export{m as __pageData,p as default};
